<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import {onMount,untrack,tick} from 'svelte';
 import {invalidateAll} from '$app/navigation';
 import type {AppData} from '#lib/client/types.ts';
 import type {AssistantSource} from '#lib/client/assistant.ts';
 import {sourceReady} from '#lib/client/assistant.ts';
 import {uploadOriginal} from '#lib/client/uploads.ts';
 import {command,statuses,permitted} from '#lib/client/api.ts';
 import AssistantSources from '../AssistantSources.svelte';
 import ReferencePicker from '../ReferencePicker.svelte';
 import Icon from '../Icon.svelte';
 let {data,revisionId,jobs=[],intent='plan',designKind='memorial',onclose}:{data:AppData;revisionId:string;jobs?:any[];intent?:'plan'|'photo';designKind?:string;onclose:()=>void}=$props();
 let dialog:HTMLDialogElement;
 let errorElement=$state<HTMLParagraphElement>();
 let mode=$state<'plan'|'photo'>(untrack(()=>intent)),prompt=$state(''),quality=$state<'low'|'medium'|'high'>('medium'),size=$state<'1024x1024'|'1536x1024'|'1024x1536'>('1536x1024');
 let rightsBasis=$state<'own_content'|'licensed_document'>('own_content'),rightsId=$state(''),statement=$state(''),rightsConfirmed=$state(false);
 let uploadNotice=$state('');
 let sources:AssistantSource[]=$state([]),busy=$state(false),refreshing=$state(false),error=$state(''),quote:any=$state(null),quotedFor=$state(''),accepted=$state(false),submittedId=$state('');
 const input=$derived({revision_id:revisionId,intent:mode,prompt:prompt.trim(),quality,size,reference_document_ids:sources.map(row=>row.documentId),reference_preview_job_ids:sources.map(row=>row.preview?.job_id??''),rights_basis:rightsBasis,...(rightsBasis==='licensed_document'?{rights_evidence_version_id:rightsId}:{}),rights_statement:rightsBasis==='own_content'?'Ich bestätige, dass ich die ausgewählten eigenen Fotos und Entwürfe für diese KI-Bildbearbeitung verwenden und an OpenAI übermitteln darf.':statement.trim()});
 const fingerprint=$derived(JSON.stringify(input));
 const qualityLabel={low:'Schneller Entwurf',medium:'Ausgewogen',high:'Hohe Detailqualität'};
 const hints=$derived(designKind==='room_plan'?['Warm & natürlich','Klar & minimalistisch','Licht & Material prüfen']:['Ruhig & natürlich','Material nah zeigen','Harmonisch bepflanzen']);
 $effect(()=>{if(quote&&quotedFor!==fingerprint){quote=null;accepted=false;}});
 $effect(()=>{if(error)void tick().then(()=>{errorElement?.focus({preventScroll:true});errorElement?.scrollIntoView({block:'nearest'});});});
 onMount(()=>{dialog.showModal();return()=>dialog.close();});
 function validate(){
  if(input.prompt.length<8)throw Error('Beschreiben Sie mit mindestens acht Zeichen, wie das Bild aussehen soll.');
  if(!rightsConfirmed)throw Error('Bestätigen Sie die Nutzungsrechte für die ausgewählten Inhalte.');
  if(rightsBasis==='licensed_document'&&(!rightsId||statement.trim().length<20))throw Error('Nutzungsnachweis und geprüften Nutzungsumfang angeben.');
  if(mode==='photo'&&!sources.length)throw Error('Wählen Sie das zu bearbeitende Foto aus und bereiten Sie es vor.');
  if(sources.length>(mode==='plan'?1:2)||sources.some(row=>!row.includeImage||!sourceReady(row,1440)||!row.preview?.job_id))throw Error('Bereiten Sie jede gewählte Bildvorlage vor und prüfen Sie die sichtbare Seite. Nicht benötigte Vorlagen entfernen.');
 }
 async function uploadPhoto(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file||busy)return;busy=true;error='';try{const result=await uploadOriginal(file,'planning_project',data.detail?.id),doc=result.document??result,id=doc.id??doc.document_id;if(id)sources=[{key:crypto.randomUUID(),documentId:id,name:file.name,pageNumber:1,includeImage:true}];uploadNotice='Foto privat gespeichert. Nach der Dateiprüfung können Sie unten die Bildvorlage vorbereiten. Das Original bleibt erhalten.';await invalidateAll();}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
 async function estimate(event:SubmitEvent){event.preventDefault();error='';busy=true;quote=null;accepted=false;try{validate();const key=fingerprint,result=await command('planning.visualization.quote',undefined,input);if(fingerprint===key){quote=result;quotedFor=key;await tick();document.getElementById('visualization-cost')?.scrollIntoView({block:'nearest',behavior:'smooth'});}}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
 async function generate(){error='';if(!quote||quotedFor!==fingerprint||!accepted)return;busy=true;try{validate();const result=await command('planning.visualization.request',quote.id,{...input,cost_acknowledged:true,approved_maximum:quote.estimatedMaxCost,request_hash:quote.requestHash},Number(quote.version));submittedId=result.id;quote=null;accepted=false;await invalidateAll();}catch(problem){error=(problem as Error).message;}finally{busy=false;}}
 async function refresh(){refreshing=true;error='';try{await invalidateAll();}catch(problem){error=(problem as Error).message;}finally{refreshing=false;}}
 function cost(value:unknown){const number=Number(value);return Number.isFinite(number)?new Intl.NumberFormat('de-DE',{minimumFractionDigits:2,maximumFractionDigits:6}).format(number):'–';}
 function download(job:any){const result=job.result;return result?.documentId&&result.documentVersionId?`/api/v1/documents/${result.documentId}/download?version=${result.documentVersionId}`:null;}
 async function continueImage(job:any){mode='photo';sources=[{key:crypto.randomUUID(),documentId:job.result.documentId,name:'Bisheriger Bildentwurf',pageNumber:1,includeImage:true}];prompt='';quote=null;accepted=false;submittedId='';await tick();document.getElementById('visualization-prompt')?.focus();}
 function useHint(hint:string){prompt=[prompt,hint+'. Fotorealistisch, mit natürlichen Materialien, glaubwürdigem Licht und ruhigen Proportionen.'].filter(Boolean).join('\n').slice(0,2000);}
</script>

<dialog bind:this={dialog} oncancel={(event)=>{if(busy)event.preventDefault();else onclose();}} aria-labelledby="visualization-title">
 <header><div><h2 id="visualization-title">Die Planung wird zum Bild.</h2><p>Material, Licht und Atmosphäre gemeinsam entwickeln.</p></div><button class="icon-button" aria-label="Bildstudio schließen" disabled={busy} onclick={onclose}><Icon name="close"/></button></header>
 <div class="content">
  {#if error}<p bind:this={errorElement} class="alert danger" role="alert" tabindex="-1">{error}</p>{/if}
  {#if submittedId}<p class="alert" role="status">Ihr Bildauftrag ist gespeichert. Sie können dieses Fenster schließen und später wieder öffnen. Über „Status aktualisieren“ sehen Sie das Ergebnis.</p>{/if}
  <form onsubmit={estimate}><fieldset disabled={busy}>
   <div class="image-modes" aria-label="Bildaufgabe"><button type="button" aria-pressed={mode==='plan'} onclick={()=>mode='plan'}><Icon name="image" size={20}/><span>Aus dem Plan<small>Gespeicherten Entwurf visualisieren</small></span></button><button type="button" aria-pressed={mode==='photo'} onclick={()=>mode='photo'}><Icon name="camera" size={20}/><span>Foto bearbeiten<small>Ein vorhandenes Bild weiterentwickeln</small></span></button></div>
   <p class="mode-note">{mode==='plan'?'Die gespeicherte Planansicht wird automatisch als Bildvorlage verwendet. Eine zusätzliche Material- oder Stilvorlage ist möglich.':'Die erste Bildvorlage ist Ihr Ausgangsfoto. Beschreiben Sie, was sich ändern soll und was erhalten bleiben muss. Eine zweite Vorlage kann Material oder Stil zeigen.'}</p>
   {#if mode==='photo'}{#if permitted(data,'documents')}<label class="photo-upload"><Icon name="upload" size={18}/><span>Neues Foto privat hochladen<small>PNG, JPG, WebP oder PDF · bis 40 MB</small></span><input aria-label="Foto für die Bildbearbeitung hochladen" type="file" accept=".png,.jpg,.jpeg,.webp,.pdf" onchange={uploadPhoto}/></label>{#if uploadNotice}<p class="alert" role="status">{uploadNotice}</p>{/if}{/if}<AssistantSources {data} bind:rows={sources} disabled={busy} imageMode maxSources={2}/><a class="text-link" href="/documents" target="_blank" rel="noreferrer">Neues Foto in Dokumente hochladen<Icon name="arrow" size={14}/></a>{/if}
   <label for="visualization-prompt">{mode==='photo'?'Was möchten Sie am Foto ändern?':'Wie soll der Entwurf wirken?'}</label><textarea id="visualization-prompt" bind:value={prompt} minlength="8" maxlength="2000" rows="4" required placeholder={mode==='photo'?'Zum Beispiel: Stein und Umgebung erhalten. Die neue Inschrift unterhalb der bestehenden Namen ergänzen, kleiner und mittig ausgerichtet.':designKind==='room_plan'?'Zum Beispiel: Perspektive vom Eingang, warmer Naturstein, indirektes Licht und natürliches Tageslicht. Die Raumaufteilung beibehalten.':'Zum Beispiel: Dunkler Granit mit fein sichtbarer Struktur, dezente Bepflanzung und weiches Morgenlicht. Proportionen der Planung beibehalten.'}></textarea>
   <div class="style-hints">{#each hints as hint}<button type="button" onclick={()=>useHint(hint)}>{hint}<Icon name="plus" size={13}/></button>{/each}</div>
   <div class="image-options"><label>Qualität<select use:searchableSelect={quality} aria-label="Qualität" bind:value={quality}><option value="low">Schneller Entwurf · sparsamer</option><option value="medium">Ausgewogen · empfohlen</option><option value="high">Hohe Detailqualität</option></select></label><label>Bildformat<select use:searchableSelect={size} aria-label="Bildformat" bind:value={size}><option value="1536x1024">Querformat · 1536 × 1024</option><option value="1024x1536">Hochformat · 1024 × 1536</option><option value="1024x1024">Quadrat · 1024 × 1024</option></select></label></div>
   {#if mode==='plan'}<details class="optional-reference"><summary>Material- oder Stilvorlage hinzufügen</summary><AssistantSources {data} bind:rows={sources} disabled={busy} imageMode maxSources={1}/></details>{/if}
   <section class="rights"><label>Herkunft der Inhalte<select use:searchableSelect={rightsBasis} bind:value={rightsBasis} onchange={()=>rightsConfirmed=false}><option value="own_content">Eigene Fotos und Entwürfe</option><option value="licensed_document">Freigegebene Inhalte mit Nutzungsnachweis</option></select></label>{#if rightsBasis==='licensed_document'}<label for="visualization-rights">Nutzungsnachweis</label><ReferencePicker id="visualization-rights" reference="document-versions" value={rightsId} initial={(data.related?.documents??[]).map((d:any)=>({id:d.version_id??d.document_version_id??d.id,name:d.name??d.original_name??'Nachweis'}))} required onchange={value=>rightsId=value}/><label class="mt">Geprüfter Nutzungsumfang<textarea bind:value={statement} minlength="20" maxlength="3000" rows="2" required placeholder="Welche Inhalte sind für diese Bildbearbeitung freigegeben?"></textarea></label>{/if}<label class="check"><input type="checkbox" bind:checked={rightsConfirmed} required/><span>Ich darf die ausgewählten Inhalte für diese Bildbearbeitung verwenden und an OpenAI übermitteln.</span></label></section>
   <button type="submit" class="btn primary" disabled={busy}><Icon name="spark" size={16}/>{busy?'Wird geprüft …':'Kosten prüfen'}</button><p class="hint">Die Kostenprüfung erstellt noch kein Bild. Erst Ihre anschließende Bestätigung startet den kostenpflichtigen Auftrag.</p>
  </fieldset></form>
  {#if quote}<section class="cost-preview" id="visualization-cost" aria-labelledby="cost-title"><h3 id="cost-title">{cost(quote.estimatedMaxCost)} {quote.currency} reservieren</h3><p>{quote.size} Pixel · {qualityLabel[quality]} · {quote.preferredModel}</p><p>Vorsichtige Kostenreservierung für diesen Auftrag. Der tatsächliche Verbrauch wird anschließend im Kosten-Dashboard erfasst. Bildkosten werden vom Anbieter nach Nutzung berechnet; die Reservierung ist kein Festpreis.</p>{#if quote.fallbackModel}<p class="hint">Falls das bevorzugte Modell nicht verfügbar ist: {quote.fallbackModel}. Kein automatischer neuer Bildauftrag nach einem unklaren Ergebnis.</p>{/if}{#if quote.protectedContent}<p class="protected">Dieser Plan enthält Bestandsinschrift. Das Bild bleibt ein interner Entwurf; die Kundenfassung benötigt die Prüfung und den Schutz der Originalpixel.</p>{/if}<label class="check"><input type="checkbox" bind:checked={accepted} disabled={busy}/><span>Ich bestätige den einzelnen kostenpflichtigen Bildauftrag und die angezeigte Reservierung.</span></label><button type="button" class="btn primary" disabled={busy||!accepted} onclick={generate}>{busy?'Auftrag wird angelegt …':'Bild jetzt erstellen'}</button></section>{/if}
  <section class="results"><div class="result-heading"><div><h3>Ihre Bildentwürfe</h3><p>Gespeichert bei diesem Planungsprojekt.</p></div><button type="button" class="btn small" disabled={refreshing||busy} onclick={refresh}><Icon name="refresh" size={15}/>{refreshing?'Wird aktualisiert …':'Status aktualisieren'}</button></div>{#each jobs as job}<article><div class="result-meta"><strong>{statuses[job.status]??'Status prüfen'}</strong><span>{job.revision_id===revisionId?'Aktueller Planstand':'Früherer Planstand'}</span></div>{#if job.last_error}<p class="job-error">{job.last_error}</p>{/if}{#if job.result?.actualCost!==undefined}<p>Tatsächliche Nutzung: {cost(job.result.actualCost)} USD</p>{/if}{#if download(job)}<a href={download(job)!} target="_blank" rel="noreferrer" data-sveltekit-reload><img src={download(job)!+'&inline=1'} alt="Gespeicherter fotorealistischer KI-Entwurf" loading="lazy"/></a><div class="result-actions"><button class="btn" type="button" disabled={busy} onclick={()=>continueImage(job)}><Icon name="edit" size={15}/>Dieses Bild weiterbearbeiten</button><a class="btn" href={download(job)!} download data-sveltekit-reload><Icon name="download" size={15}/>Herunterladen</a></div><p class="hint">KI-Konzept · keine technische Zeichnung{#if job.result?.protectedContentRequiresComposite} · Originalpixel vor Kundenverwendung schützen{/if}</p>{/if}</article>{:else}<div class="empty-images"><Icon name="image" size={28}/><p>Hier erscheinen Ihre gespeicherten Bildentwürfe. Sie können jedes fertige Bild anschließend weiterbearbeiten.</p></div>{/each}</section>
 </div><footer><p>Bearbeitbarer Plan, technische 3D-Ansicht und Exporte stehen im Studio bereit.</p><button type="button" class="btn" disabled={busy} onclick={onclose}>Zurück zum Plan</button></footer>
</dialog>

<style>.photo-upload{display:flex;align-items:center;flex-wrap:wrap;gap:13px;padding:17px;background:var(--wash);border:1px dashed var(--line);border-radius:11px;margin:0 0 18px}.photo-upload>span{flex:1;min-width:180px}.photo-upload small{display:block;color:var(--muted);font-size:12px;margin-top:5px}.photo-upload input{width:100%;font:inherit;font-size:13px;min-height:40px}.photo-upload input::file-selector-button{border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:7px;padding:9px 12px;margin-right:10px}
 dialog{width:min(820px,calc(100vw - 32px));max-height:94dvh;padding:0;border:1px solid var(--line);border-radius:18px;background:var(--paper);color:var(--ink);box-shadow:0 24px 100px #0004}dialog::backdrop{background:#101b17a8;backdrop-filter:blur(6px)}header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:28px 32px 22px;border-bottom:1px solid var(--line)}header h2{font-size:28px;letter-spacing:-.04em;font-weight:550;margin:10px 0}header p{margin:0}p{font-size:13px;line-height:1.75;color:var(--muted);margin:10px 0}.content{padding:26px 32px;max-height:calc(94dvh - 235px);overflow-y:auto;overscroll-behavior:contain}fieldset{padding:0;margin:0;border:0;min-width:0}label{display:block;font-size:13px;line-height:1.6;margin-bottom:8px;color:var(--ink)}textarea,select{box-sizing:border-box;width:100%;padding:12px;min-height:46px;margin:7px 0 14px;border:1px solid var(--line);border-radius:9px;background:var(--paper);color:var(--ink);font:inherit;font-size:14px}textarea{resize:vertical}.image-modes{display:grid;grid-template-columns:1fr 1fr;gap:10px}.image-modes button{display:flex;align-items:center;gap:12px;text-align:left;border:1px solid var(--line);background:var(--paper);border-radius:11px;padding:16px;color:var(--ink);font-size:14px;min-width:0}.image-modes button[aria-pressed=true]{border-color:var(--forest);background:var(--wash);box-shadow:inset 0 0 0 1px var(--forest)}.image-modes small{display:block;font-size:11px;color:var(--muted);font-weight:400;margin-top:5px;line-height:1.5}.image-modes :global(svg){flex:none}.mode-note{margin:14px 0 24px}.image-options{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:22px}.style-hints{display:flex;flex-wrap:wrap;gap:8px;margin-top:-4px}.style-hints button{display:flex;align-items:center;gap:8px;background:var(--wash);border:0;border-radius:7px;color:var(--muted);font-size:12px;min-height:36px;padding:7px 10px}.optional-reference{margin:8px 0 20px}.rights{margin:18px 0;padding:18px;border:1px solid var(--line);border-radius:11px}.rights select{margin-bottom:10px}.check{display:flex;gap:10px;align-items:flex-start;font-size:12px;line-height:1.65;margin:10px 0 0}.check input{width:17px;height:17px;flex:none;margin-top:2px;accent-color:var(--forest)}.hint{font-size:12px}.cost-preview{padding:22px;margin:24px 0;border:1px solid var(--forest);background:var(--wash);border-radius:12px}.cost-preview h3{font-size:25px;letter-spacing:-.03em;font-weight:550}.cost-preview .check{margin:18px 0}.protected{background:var(--warning-wash);color:var(--warning);padding:12px;border-radius:8px}.alert{padding:14px;border-radius:9px;border:1px solid var(--line);background:var(--wash);white-space:pre-wrap}.alert.danger{background:var(--danger-wash);color:var(--danger)}.results{border-top:1px solid var(--line);margin-top:28px;padding-top:24px}.result-heading{display:flex;gap:15px;align-items:center;justify-content:space-between;flex-wrap:wrap}.result-heading h3{font-size:18px;font-weight:550}.result-heading p{margin:6px 0 0}.results article{padding:22px 0;border-bottom:1px solid var(--line)}.result-meta{display:flex;justify-content:space-between;gap:12px;font-size:13px}.result-meta>span{color:var(--muted);font-size:12px}.results img{display:block;width:100%;max-height:500px;object-fit:contain;margin:16px 0;border-radius:10px;background:var(--wash)}.result-actions{display:flex;gap:10px;flex-wrap:wrap}.empty-images{padding:30px 20px;text-align:center;color:var(--muted)}.empty-images p{max-width:400px;margin:12px auto}.job-error{color:var(--danger);white-space:pre-wrap}footer{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px 32px;border-top:1px solid var(--line)}footer p{font-size:12px;max-width:380px;margin:0}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--forest);outline-offset:3px}@media(max-width:600px){dialog{width:calc(100vw - 16px);border-radius:14px}header,.content{padding:22px}header h2{font-size:25px}.content{max-height:calc(94dvh - 260px)}.image-modes{grid-template-columns:1fr}.image-options{grid-template-columns:1fr;gap:0}textarea,select{font-size:16px}.image-modes small{font-size:12px}.btn{min-height:46px}.style-hints button{min-height:42px}.check{font-size:13px}footer{padding:16px 22px;flex-wrap:wrap}footer .btn{width:100%}}
dialog[open]{display:flex;flex-direction:column}header,footer{flex-shrink:0}.content{flex:1;min-height:0;max-height:none}@media(max-width:600px){.content{max-height:none}}
</style>
